  1→import express, { Request, Response } from "express";
  2→import { query, AgentDefinition, SettingSource, HookCallbackMatcher } from "@anthropic-ai/claude-agent-sdk";
  3→import { Langfuse } from "langfuse";
  4→import { mkdirSync, writeFileSync, existsSync, readdirSync, readFileSync } from "fs";
  5→import { homedir } from "os";
  6→import { join } from "path";
  7→import type { QueryRequest, HealthResponse, AgentDefinitionPayload } from "./types.js";
  8→
  9→// Claude CLI requires certain directories/files under ~/.claude to exist.
 10→// The container uses a tmpfs mount at ~/.claude which starts empty, so we
 11→// create the expected structure at startup.
 12→const claudeDir = join(homedir(), ".claude");
 13→for (const sub of ["debug", "projects"]) {
 14→  const dir = join(claudeDir, sub);
 15→  if (!existsSync(dir)) {
 16→    mkdirSync(dir, { recursive: true });
 17→  }
 18→}
 19→const settingsFile = join(claudeDir, "remote-settings.json");
 20→if (!existsSync(settingsFile)) {
 21→  writeFileSync(settingsFile, "{}");
 22→}
 23→
 24→const SKILLS_DIR = join(homedir(), ".claude", "skills");
 25→
 26→function isSkillDisabled(skillPath: string): boolean {
 27→  try {
 28→    const text = readFileSync(skillPath, "utf-8");
 29→    if (!text.startsWith("---")) return false;
 30→    const end = text.indexOf("---", 3);
 31→    if (end === -1) return false;
 32→    const frontmatter = text.slice(3, end);
 33→    for (const line of frontmatter.split("\n")) {
 34→      if (line.trim().startsWith("disabled:") && line.trim().endsWith("true")) {
 35→        return true;
 36→      }
 37→    }
 38→  } catch {
 39→    // ignore read errors
 40→  }
 41→  return false;
 42→}
 43→
 44→function discoverSkills(): Set<string> {
 45→  if (!existsSync(SKILLS_DIR)) return new Set();
 46→  return new Set(
 47→    readdirSync(SKILLS_DIR, { withFileTypes: true })
 48→      .filter((d) => {
 49→        if (!d.isDirectory()) return false;
 50→        const skillPath = join(SKILLS_DIR, d.name, "SKILL.md");
 51→        return existsSync(skillPath) && !isSkillDisabled(skillPath);
 52→      })
 53→      .map((d) => d.name)
 54→  );
 55→}
 56→
 57→// Log initial skills at startup
 58→console.log(`[sidecar] Initial skills: ${[...discoverSkills()].join(", ") || "(none)"}`);
 59→
 60→const skillAllowlistHook: HookCallbackMatcher = {
 61→  matcher: "Skill",
 62→  hooks: [
 63→    async (input) => {
 64→      const currentSkills = discoverSkills();
 65→      const toolInput = (input as Record<string, unknown>).tool_input as Record<string, unknown> | undefined;
 66→      const skillName = toolInput?.skill as string | undefined;
 67→      if (skillName && !currentSkills.has(skillName)) {
 68→        return {
 69→          hookSpecificOutput: {
 70→            hookEventName: "PreToolUse" as const,
 71→            permissionDecision: "deny" as const,
 72→            permissionDecisionReason: `Skill "${skillName}" is not in the allowlist.`,
 73→          },
 74→        };
 75→      }
 76→      return {};
 77→    },
 78→  ],
 79→};
 80→
 81→// Initialize Langfuse if credentials are available (reads from env vars
 82→// LANGFUSE_PUBLIC_KEY, LANGFUSE_SECRET_KEY, LANGFUSE_BASE_URL automatically)
 83→let langfuse: Langfuse | null = null;
 84→if (process.env.LANGFUSE_PUBLIC_KEY && process.env.LANGFUSE_SECRET_KEY) {
 85→  langfuse = new Langfuse();
 86→  console.log("[sidecar] Langfuse tracing enabled");
 87→}
 88→
 89→const app = express();
 90→app.use(express.json({ limit: "10mb" }));
 91→
 92→const PORT = parseInt(process.env.PORT || "3000", 10);
 93→
 94→// Per-request abort tracking — avoids a global variable whose cleanup in one
 95→// request's `finally` block can clobber a concurrently-started request.
 96→let nextRequestId = 0;
 97→const activeAborts = new Map<number, AbortController>();
 98→
 99→// How long (ms) to wait for the SDK iterator to yield a message before
100→// aborting.  Resets on every message so active multi-turn queries are not
101→// interrupted.  Covers cases where the CLI subprocess hangs on startup
102→// (e.g. broken session resume, unreachable MCP server).
103→const SDK_IDLE_TIMEOUT_MS = parseInt(process.env.SDK_IDLE_TIMEOUT_MS || "120000", 10);
104→
105→// Timeout (ms) for pre-flight reachability checks against MCP / API URLs.
106→const PREFLIGHT_TIMEOUT_MS = 10_000; // 10 seconds
107→
108→app.get("/health", (_req: Request, res: Response) => {
109→  const response: HealthResponse = { status: "ok" };
110→  res.json(response);
111→});
112→
113→app.post("/query", async (req: Request, res: Response) => {
114→  const body = req.body as QueryRequest;
115→
116→  if (!body.message || !body.system_prompt) {
117→    res.status(400).json({ error: "message and system_prompt are required" });
118→    return;
119→  }
120→
121→  // Set up SSE headers
122→  res.setHeader("Content-Type", "text/event-stream");
123→  res.setHeader("Cache-Control", "no-cache");
124→  res.setHeader("Connection", "keep-alive");
125→  res.setHeader("X-Accel-Buffering", "no");
126→  res.flushHeaders();
127→
128→  const abortController = new AbortController();
129→  const requestId = nextRequestId++;
130→  activeAborts.set(requestId, abortController);
131→
132→  // Merge per-request env overrides (e.g. Bifrost gateway URLs) with process env
133→  const sdkEnv: Record<string, string> = {};
134→  for (const [k, v] of Object.entries(process.env)) {
135→    if (v !== undefined) sdkEnv[k] = v;
136→  }
137→  if (body.env) {
138→    Object.assign(sdkEnv, body.env);
139→  }
140→  // Scrub Langfuse credentials so the agent subprocess cannot read them from
141→  // the inherited environment — matches backend subprocess behaviour.
142→  // The sidecar's own Langfuse client already holds the credentials internally.
143→  sdkEnv["LANGFUSE_PUBLIC_KEY"] = "";
144→  sdkEnv["LANGFUSE_SECRET_KEY"] = "";
145→
146→  let responseEnded = false;
147→
148→  // Detect client disconnect
149→  res.on("close", () => {
150→    if (!responseEnded) {
151→      abortController.abort();
152→    }
153→  });
154→
155→  // --- Langfuse tracing setup ---
156→  // Mirror the backend's session ID handling:
157→  //   - langfuse_session_id (from frontend for edit/delete) takes priority
158→  //   - session_id (CLI session from previous turn) as fallback
159→  const modelName = body.model || process.env.ORCHESTRATOR_MODEL || "claude-sonnet-4-6";
160→  const traceMessage = body.original_message || body.message;
161→  const traceInput: Record<string, unknown> = {
162→    message: traceMessage.substring(0, 500),
163→  };
164→  if (body.conversation_history && body.conversation_history.length > 0) {
165→    traceInput.conversation_history = body.conversation_history;
166→  }
167→  const trace = langfuse?.trace({
168→    name: "agent-chat",
169→    sessionId: body.langfuse_session_id || body.session_id || undefined,
170→    input: traceInput,
171→    metadata: { model: modelName, mode: "container" },
172→  });
173→
174→  // Per-turn usage tracking from stream events
175→  let currentGenUsage: { input?: number; output?: number } = {};
176→  // Accumulated messages for generation input context
177→  const accumulatedMessages: Array<{ role: string; content: unknown }> = [
178→    { role: "user", content: body.message },
179→  ];
180→
181→  // Collect stderr from the CLI subprocess for debugging
182→  const stderrLines: string[] = [];
183→
184→  // Declared here so `finally` can clear it even if `try` throws early
185→  let idleTimer: ReturnType<typeof setTimeout> | null = null;
186→
187→  try {
188→    // --- Pre-flight reachability checks ---
189→    // The CLI subprocess will hang silently if it can't reach the MCP SSE
190→    // server or the Bifrost LLM gateway.  Test connectivity first so we can
191→    // fail fast with a useful error message.
192→    const apiBase = sdkEnv["ANTHROPIC_BASE_URL"] || "";
193→    console.log(
194→      `[sidecar] reqId=${requestId} mcp_url=${body.mcp_server_url || "(none)"} api_base=${apiBase} session_id=${body.session_id || "(none)"}`
195→    );
196→
197→    if (body.mcp_server_url) {
198→      try {
199→        const mcpResp = await fetch(body.mcp_server_url, {
200→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
201→        });
202→        // SSE endpoints normally return 200 with text/event-stream; any
203→        // non-error status is fine — we just need to know the host is up.
204→        mcpResp.body?.cancel(); // don't consume the stream
205→        console.log(`[sidecar] MCP reachability OK (status=${mcpResp.status})`);
206→      } catch (e: unknown) {
207→        const reason = e instanceof Error ? e.message : String(e);
208→        throw new Error(
209→          `MCP server unreachable at ${body.mcp_server_url}: ${reason}. ` +
210→          `Check that BACKEND_BASE_URL is reachable from inside the container.`
211→        );
212→      }
213→    }
214→
215→    if (apiBase) {
216→      try {
217→        // Just a quick TCP-level check — Bifrost will return 4xx without
218→        // a real API key but that still proves reachability.
219→        const apiResp = await fetch(`${apiBase}/v1/models`, {
220→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
221→        });
222→        apiResp.body?.cancel();
223→        console.log(`[sidecar] Bifrost LLM gateway reachability OK (status=${apiResp.status})`);
224→      } catch (e: unknown) {
225→        const reason = e instanceof Error ? e.message : String(e);
226→        throw new Error(
227→          `Bifrost LLM gateway unreachable at ${apiBase}: ${reason}. ` +
228→          `Check that BIFROST_BASE_URL is reachable from inside the container.`
229→        );
230→      }
231→    }
232→
233→    // Convert agents payload from the backend into SDK AgentDefinition objects.
234→    // The SDK only accepts 'sonnet' | 'opus' | 'haiku' | 'inherit' for model.
235→    // Arbitrary strings (e.g. "openai/gpt-5.2") are silently rejected, causing
236→    // the agent to not be registered.  Validate and fall back to "inherit".
237→    const VALID_AGENT_MODELS = new Set(["sonnet", "opus", "haiku", "inherit"]);
238→    let sdkAgents: Record<string, AgentDefinition> | undefined;
239→    if (body.agents) {
240→      sdkAgents = {};
241→      for (const [name, def] of Object.entries(body.agents)) {
242→        const model = def.model && VALID_AGENT_MODELS.has(def.model)
243→          ? (def.model as AgentDefinition["model"])
244→          : "inherit";
245→        sdkAgents[name] = {
246→          description: def.description,
247→          prompt: def.prompt,
248→          ...(def.tools ? { tools: def.tools } : {}),
249→          model,
250→        };
251→      }
252→    }
253→
254→    // Append skill restriction so the model doesn't list or suggest
255→    // built-in skills that the PreToolUse hook would block anyway.
256→    // The CLI binary injects its own system reminder listing ALL skills
257→    // (including built-ins like "simplify"), so we must explicitly tell
258→    // the model to ignore any skills not in our allowlist.
259→    const currentSkills = discoverSkills();
260→    const allowedList = [...currentSkills].join(", ");
261→    const skillRestriction = currentSkills.size > 0
262→      ? `\n\nCRITICAL SKILL RESTRICTION: Your ONLY available skills are: ${allowedList}. You may see other skills (like "simplify") listed in system reminders — those are NOT available to you and MUST be ignored. When asked about available skills, list ONLY: ${allowedList}. Never mention, suggest, or attempt to invoke any skill not in this list.`
263→      : "\n\nCRITICAL SKILL RESTRICTION: You have NO skills available. You may see skills listed in system reminders — those are NOT available to you and MUST be ignored. Never mention, suggest, or attempt to invoke any skills.";
264→
265→    const skillInstruction = body.skills?.length
266→      ? `\n\nIMPORTANT: The user has invoked the following skill(s): ${body.skills.map(s => `"/${s}"`).join(", ")}. You MUST use the Skill tool to invoke each skill (${body.skills.map(s => `"${s}"`).join(", ")}) before doing anything else.`
267→      : "";
268→
269→    // Common SDK options (without resume/prompt — those vary on retry)
270→    const baseOptions = {
271→      model: modelName,
272→      systemPrompt: body.system_prompt + skillInstruction + skillRestriction,
273→      allowedTools: ["Skill", "Task", "mcp__duckdb-data-agent__execute_sql", "mcp__duckdb-data-agent__ask_user_question", "mcp__duckdb-data-agent__render_chart", "mcp__duckdb-data-agent__create_skill"] as string[],
274→      settingSources: ["project"] as SettingSource[],
275→      plugins: [],
276→      hooks: { PreToolUse: [skillAllowlistHook] },
277→      permissionMode: "bypassPermissions" as const,
278→      allowDangerouslySkipPermissions: true,
279→      maxTurns: 20,
280→      includePartialMessages: true,
281→      abortController,
282→      env: sdkEnv,
283→      stderr: (line: string) => {
284→        stderrLines.push(line);
285→        console.error(`[sidecar:cli] ${line}`);
286→      },
287→      ...(sdkAgents ? { agents: sdkAgents } : {}),
288→      ...(body.mcp_server_url
289→        ? {
290→            mcpServers: {
291→              "duckdb-data-agent": {
292→                type: "sse" as const,
293→                url: body.mcp_server_url,
294→              },
295→            },
296→          }
297→        : {}),
298→    };
299→
300→    // Resume fallback: try with resume first. If the SDK yields a "result"
301→    // message with "No conversation found" (container was recreated and lost
302→    // the session), suppress that error and retry without resume, prepending
303→    // conversation history so the model has context.
304→    //
305→    // When resuming, the SDK reuses the original session's system prompt, so
306→    // skill changes (additions/deletions) since conversation start won't be
307→    // reflected.  Prepend an updated skill restriction to the user message so
308→    // the model always sees the current set of available skills.
309→    let useResume = !!body.session_id;
310→    let currentPrompt = useResume
311→      ? `${skillRestriction}\n\n${body.message}`
312→      : body.message;
313→    let retried = false;
314→
315→    queryLoop: for (let attempt = 0; attempt < 2; attempt++) {
316→      const sdkQuery = query({
317→        prompt: currentPrompt,
318→        options: {
319→          ...baseOptions,
320→          ...(useResume ? { resume: body.session_id } : {}),
321→        },
322→      });
323→
324→      console.log(
325→        `[sidecar] SDK query started model=${modelName} reqId=${requestId} attempt=${attempt} resume=${useResume}`
326→      );
327→
328→      idleTimer = setTimeout(() => {
329→        console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
330→        abortController.abort();
331→      }, SDK_IDLE_TIMEOUT_MS);
332→
333→      let resumeFailedNeedsRetry = false;
334→
335→      try {
336→        for await (const message of sdkQuery) {
337→          // Reset idle timer on every message
338→          if (idleTimer) { clearTimeout(idleTimer); }
339→          idleTimer = setTimeout(() => {
340→            console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
341→            abortController.abort();
342→          }, SDK_IDLE_TIMEOUT_MS);
343→
344→          if (responseEnded) break queryLoop;
345→
346→          // Intercept "No conversation found" result before forwarding
347→          if (useResume && !retried) {
348→            const msg = message as Record<string, unknown>;
349→            if (msg.type === "result" && msg.is_error) {
350→              const resultText = String(msg.result || "");
351→              const errors = ((msg.errors as string[]) || []).join(" ");
352→              if ((resultText + " " + errors).includes("No conversation found")
353→                  && body.conversation_history && body.conversation_history.length > 0) {
354→                console.log(`[sidecar] Resume failed ("No conversation found"), will retry with history reqId=${requestId}`);
355→                resumeFailedNeedsRetry = true;
356→                break; // Don't forward this error to the client
357→              }
358→            }
359→          }
360→
361→          // Forward each SDK message as an SSE data line
362→          res.write(`data: ${JSON.stringify(message)}\n\n`);
363→
364→          // --- Create Langfuse observations from SDK messages ---
365→          if (!trace) continue;
366→          const msg = message as Record<string, unknown>;
367→
368→          if (msg.type === "stream_event") {
369→            const event = (msg.event as Record<string, unknown>) || {};
370→            const eventType = event.type as string;
371→            if (eventType === "message_start") {
372→              const msgData = (event.message as Record<string, unknown>) || {};
373→              const usage = (msgData.usage as Record<string, number>) || {};
374→              currentGenUsage = { input: usage.input_tokens || 0 };
375→            } else if (eventType === "message_delta") {
376→              const usage = (event.usage as Record<string, number>) || {};
377→              currentGenUsage.output = usage.output_tokens || 0;
378→            }
379→          } else if (msg.type === "assistant") {
380→            const msgObj = (msg.message as Record<string, unknown>) || {};
381→            const content = msgObj.content as unknown[];
382→            const usage =
383→              currentGenUsage.input !== undefined
384→                ? {
385→                    input: currentGenUsage.input || 0,
386→                    output: currentGenUsage.output || 0,
387→                    total: (currentGenUsage.input || 0) + (currentGenUsage.output || 0),
388→                    unit: "TOKENS" as const,
389→                  }
390→                : undefined;
391→            const gen = trace.generation({
392→              name: "claude.assistant.turn",
393→              model: (msgObj.model as string) || modelName,
394→              input: { messages: accumulatedMessages.slice(-6) },
395→              output: { content, role: "assistant" },
396→              usage,
397→            });
398→            gen.end();
399→            currentGenUsage = {};
400→            accumulatedMessages.push({ role: "assistant", content });
401→          } else if (msg.type === "user") {
402→            const msgObj = (msg.message as Record<string, unknown>) || {};
403→            accumulatedMessages.push({ role: "user", content: msgObj.content });
404→          } else if (msg.type === "result") {
405→            const actualSessionId = (msg.session_id as string | undefined) || body.session_id;
406→            const traceSessionId = body.langfuse_session_id || actualSessionId;
407→            trace.update({
408→              ...(traceSessionId ? { sessionId: traceSessionId } : {}),
409→              output: { session_id: actualSessionId },
410→            });
411→          } else if (msg.type === "system") {
412→            const sessionId = msg.session_id as string | undefined;
413→            if (sessionId && !body.langfuse_session_id) {
414→              trace.update({ sessionId });
415→            }
416→          }
417→        } // end for-await
418→      } catch (innerErr: unknown) {
419→        // If we're retrying due to resume failure, swallow the cleanup error
420→        // (e.g., "Claude Code process exited with code 1" after session not found)
421→        if (resumeFailedNeedsRetry) {
422→          console.log(`[sidecar] Swallowing post-resume error during retry: ${innerErr instanceof Error ? innerErr.message : String(innerErr)}`);
423→        } else {
424→          throw innerErr;
425→        }
426→      }
427→
428→      if (resumeFailedNeedsRetry && !retried) {
429→        retried = true;
430→        useResume = false;
431→        let messageWithHistory = "Previous conversation (for context):\n";
432→        for (const entry of body.conversation_history!) {
433→          const role = (entry.role || "user").charAt(0).toUpperCase() + (entry.role || "user").slice(1);
434→          messageWithHistory += `\n${role}: ${entry.content}\n`;
435→        }
436→        messageWithHistory += `\n---\n\nMy new message:\n${body.message}`;
437→        currentPrompt = messageWithHistory;
438→        stderrLines.length = 0;
439→        if (idleTimer) { clearTimeout(idleTimer); idleTimer = null; }
440→        continue; // retry the queryLoop
441→      }
442→
443→      break; // success or non-retryable error — exit queryLoop
444→    } // end queryLoop
445→  } catch (err: unknown) {
446→    let errMsg = err instanceof Error ? err.message : String(err);
447→    // Append CLI stderr for context when the process crashes
448→    if (stderrLines.length > 0) {
449→      errMsg += ` | CLI stderr: ${stderrLines.slice(-5).join(" ")}`;
450→    }
451→    // Don't log abort errors — they are expected on client disconnect
452→    if (!(err instanceof Error && err.name === "AbortError")) {
453→      console.error(`[sidecar] SDK error: ${errMsg}`);
454→      if (!responseEnded) {
455→        res.write(
456→          `data: ${JSON.stringify({ type: "error", message: errMsg })}\n\n`
457→        );
458→      }
459→      if (trace) {
460→        trace.update({ output: { error: errMsg } });
461→      }
462→    }
463→  } finally {
464→    if (idleTimer) { clearTimeout(idleTimer); }
465→    activeAborts.delete(requestId);
466→    responseEnded = true;
467→    res.end();
468→    // Flush Langfuse events before the response is fully closed
469→    if (langfuse) {
470→      await langfuse.flushAsync().catch(() => {});
471→    }
472→    console.log(`[sidecar] SSE stream ended reqId=${requestId}`);
473→  }
474→});
475→
476→app.post("/stop", (_req: Request, res: Response) => {
477→  if (activeAborts.size > 0) {
478→    for (const [id, controller] of activeAborts) {
479→      controller.abort();
480→      activeAborts.delete(id);
481→    }
482→    res.json({ status: "stopped" });
483→  } else {
484→    res.json({ status: "no_active_session" });
485→  }
486→});
487→
488→app.listen(PORT, "0.0.0.0", () => {
489→  console.log(`Sidecar agent server listening on port ${PORT}`);
490→});
