194→      `[sidecar] reqId=${requestId} mcp_url=${body.mcp_server_url || "(none)"} api_base=${apiBase} session_id=${body.session_id || "(none)"}`
195→    );
196→
197→    if (body.mcp_server_url) {
198→      try {
199→        const mcpResp = await fetch(body.mcp_server_url, {
200→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
201→        });
