358→            }
359→          }
360→
361→          // Forward each SDK message as an SSE data line
362→          res.write(`data: ${JSON.stringify(message)}\n\n`);
363→
364→          // --- Create Langfuse observations from SDK messages ---
365→          if (!trace) continue;
366→          const msg = message as Record<string, unknown>;
367→
368→          if (msg.type === "stream_event") {
369→            const event = (msg.event as Record<string, unknown>) || {};
370→            const eventType = event.type as string;
371→            if (eventType === "message_start") {
372→              const msgData = (event.message as Record<string, unknown>) || {};
373→              const usage = (msgData.usage as Record<string, number>) || {};
