392→              name: "claude.assistant.turn",
393→              model: (msgObj.model as string) || modelName,
394→              input: { messages: accumulatedMessages.slice(-6) },
395→              output: { content, role: "assistant" },
396→              usage,
397→            });
398→            gen.end();
399→            currentGenUsage = {};
400→            accumulatedMessages.push({ role: "assistant", content });
401→          } else if (msg.type === "user") {
402→            const msgObj = (msg.message as Record<string, unknown>) || {};
403→            accumulatedMessages.push({ role: "user", content: msgObj.content });
404→          } else if (msg.type === "result") {
405→            const actualSessionId = (msg.session_id as string | undefined) || body.session_id;
406→            const traceSessionId = body.langfuse_session_id || actualSessionId;
407→            trace.update({
408→              ...(traceSessionId ? { sessionId: traceSessionId } : {}),
409→              output: { session_id: actualSessionId },
410→            });
411→          } else if (msg.type === "system") {
412→            const sessionId = msg.session_id as string | undefined;
413→            if (sessionId && !body.langfuse_session_id) {
